// ============================================================
// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
	if dst.LetsEncryptEmail == "" {
		dst.LetsEncryptEmail = src.LetsEncryptEmail
	}
	if dst.HttpListen == "" {
		dst.HttpListen = src.HttpListen
	}
	if dst.RenewalCheckIntervalSeconds == 0 {
		dst.RenewalCheckIntervalSeconds = src.RenewalCheckIntervalSeconds
	}
}

// ============================================================
// Merge: LetsEncryptState
// ============================================================
// MergeLetsEncryptState fills zero-valued fields in dst from src.
func MergeLetsEncryptState(dst, src *LetsEncryptState) {
	if dst.CertData == nil {
		dst.CertData = src.CertData
	} else if src.CertData != nil {
		MergeLetsEncryptCertData(dst.CertData, src.CertData)
	}
}

// ============================================================
// Merge: LetsEncryptCertData
// ============================================================
// MergeLetsEncryptCertData fills zero-valued fields in dst from src.
func MergeLetsEncryptCertData(dst, src *LetsEncryptCertData) {
	if dst.TlsCert == nil {
		dst.TlsCert = src.TlsCert
	}
	if dst.CertmagicState == nil {
		dst.CertmagicState = src.CertmagicState
	} else if src.CertmagicState != nil {
		MergeCertMagicState(dst.CertmagicState, src.CertmagicState)
	}
	if dst.LastRenewed == 0 {
		dst.LastRenewed = src.LastRenewed
	}
	if dst.Fqdn == "" {
		dst.Fqdn = src.Fqdn
	}
}

// ============================================================
// Merge: CertMagicState
// ============================================================
// MergeCertMagicState fills zero-valued fields in dst from src.
func MergeCertMagicState(dst, src *CertMagicState) {
	if !dst.IsDir {
		dst.IsDir = src.IsDir
	}
	if len(dst.Value) == 0 {
		dst.Value = src.Value
	}
	if dst.ModTime == 0 {
		dst.ModTime = src.ModTime
	}
}

// ============================================================
// Merge: LetsencryptConfigState
// ============================================================
// MergeLetsencryptConfigState fills zero-valued fields in dst from src.
func MergeLetsencryptConfigState(dst, src *LetsencryptConfigState) {
	if dst.Config == nil {
		dst.Config = src.Config
	} else if src.Config != nil {
		MergeConfig(dst.Config, src.Config)
	}
}

